const getStatusBadgeStyles = (status: string) => {
  switch(status){
    case "В пути на склад Китая": return {bg:"bg-blue-50 text-blue-700 border-blue-200",bgHover:"hover:bg-blue-100",dot:"bg-blue-500",rowBg:"bg-blue-50/20",colorText:"text-blue-800"};
    case "На складе в Китае": return {bg:"bg-amber-50 text-amber-800 border-amber-200",bgHover:"hover:bg-amber-100",dot:"bg-amber-500",rowBg:"bg-amber-50/20",colorText:"text-amber-900"};
    case "Едет в РБ": return {bg:"bg-indigo-50 text-indigo-700 border-indigo-200",bgHover:"hover:bg-indigo-100",dot:"bg-indigo-500",rowBg:"bg-indigo-50/20",colorText:"text-indigo-800"};
    case "Прибыло в РБ": return {bg:"bg-emerald-50 text-emerald-700 border-emerald-200",bgHover:"hover:bg-emerald-100",dot:"bg-emerald-500",rowBg:"bg-emerald-50/25",colorText:"text-emerald-800"};
    case "Выдано / Получено": return {bg:"bg-slate-100 text-slate-700 border-slate-200",bgHover:"hover:bg-slate-200",dot:"bg-slate-400",rowBg:"bg-slate-50/10",colorText:"text-slate-800"};
    default: return {bg:"bg-gray-100 text-gray-700 border-gray-200",bgHover:"hover:bg-gray-200",dot:"bg-gray-400",rowBg:"",colorText:"text-gray-800"};
  }
};

